import { Button, Divider, Input } from "@egarciadececa/react-components";
import React, { useContext } from "react";
import { useNavigate } from "react-router-dom";
import styled from "styled-components";

import { ModalOp } from "../reducers/modal-types";
import { signIn } from "../services/api/routes";
import { setAuthenticationToken } from "../services/api/token";

import { ModalContext } from "./Root";

const TitleDiv = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const StyledForm = styled.form`
  margin: 1rem auto;
  border: 1px solid;
  border-radius: 1rem;
  padding: 1rem;

  background-color: ${(props) => props.theme.neutral.foreground};
  border-color: ${(props) => props.theme.neutral.border};
  color: ${(props) => props.theme.neutral.text};

  max-width: 500px;

  display: flex;
  flex-direction: column;
  align-items: stretch;
`;

export default function SignIn() {
  const [email, setEmail] = React.useState("");
  const [password, setPassword] = React.useState("");

  const openModal = useContext(ModalContext);
  const navigate = useNavigate();

  async function submit() {
    try {
      if (!email || !password) {
        openModal({
          type: ModalOp.OPEN_ERROR_MODAL,
          message: "Fill out all the fields",
        });
      } else {
        const token = await signIn({ email, password });
        setAuthenticationToken(token);
        navigate("/");
      }
    } catch (error: any) {
      openModal({
        type: ModalOp.OPEN_ERROR_MODAL,
        message: error?.message || "An error occurred",
      });
    }
  }
  return (
    <>
      <TitleDiv>
        <h1>Sign in</h1>
      </TitleDiv>
      <StyledForm
        onSubmit={(e) => {
          e.stopPropagation();
          e.preventDefault();
          submit();
        }}
      >
        <Input
          type="email"
          id="email"
          tagText="Email"
          value={email}
          onChange={setEmail}
        />
        <Input
          type="password"
          id="password"
          tagText="Password"
          value={password}
          onChange={setPassword}
        />

        <Divider />

        <Button as="button" type="submit">
          Sign in
        </Button>
      </StyledForm>
    </>
  );
}
